SELECT id, host, latency_ms, status_code, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, COALESCE(context['version'], 'unknown') AS version_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE latency_ms <> 1448
